        ["LmntDirectory"] = ("LMNT-Serverliste (optional)", "LMNT directory (optional)"),
        ["SetupStep1"] = ("1 · Server verbinden", "1 · Connect your server"),
        ["SetupStep1Hint"] = ("Trage Host, RCON-Zugang und den ggCON-HTTP-Port ein. Die HTTP API übernimmt Spieler, Chatlogs und viele Aktionen; RCON wird bei Bedarf verbunden. Die Zugangsdaten erhältst du von deinem Hoster oder aus deiner ggCON-Konfiguration.", "Enter the host, RCON credentials and ggCON HTTP port. The HTTP API handles players, chat logs and many actions; RCON connects on demand. Get the credentials from your host or ggCON configuration."),
        ["SetupStep2"] = ("2 · Dateizugriff nur bei Bedarf", "2 · File access when needed"),
        ["SetupStep2Hint"] = ("SFTP wird für SCUM.db, ServerSettings.ini, EconomyOverride.json und dateibasierte Logs benötigt. Für reine HTTP-Funktionen brauchst du keinen SFTP-Zugang. Die vollständigen Dateipfade stellst du bei Herausforderungen, Randomizer und Economy ein.", "SFTP is needed for SCUM.db, ServerSettings.ini, EconomyOverride.json and file-based logs. HTTP-only features do not require SFTP. Set full file paths under Challenges, Randomizer and Economy."),
        ["SetupStep3"] = ("3 · Funktionen einzeln einrichten und testen", "3 · Set up and test each feature"),
        ["SetupStep3Hint"] = ("Discord: Bot-Token und Channel-IDs. Chat Commands: Befehle, Begrüßung und Votes. Herausforderungen: Datenbank, Ziele und Rewards. Erst nach einem erfolgreichen Test den gewünschten Autostart aktivieren.", "Discord: bot token and channel IDs. Chat commands: commands, welcome messages and votes. Challenges: database, goals and rewards. Enable automatic startup only after a successful test."),
        ["SetupOptionalHint"] = ("Homepage-Anbindungen, LMNT-Serverliste und Update-Quellen sind optional. Du findest sie unter Erweitert; für den normalen Betrieb brauchst du diesen Bereich nicht.", "Website connections, the LMNT directory and update sources are optional. Find them under Advanced; this section is not needed for normal operation."),
        ["SetupSaveHint"] = ("Änderungen werden erst mit Speichern dauerhaft übernommen. Laufende Dienste bei geänderten Verbindungsdaten stoppen und erneut starten.", "Changes are persisted only when you save. Stop and restart running services after changing connection credentials."),
        ["SetupRconHint"] = ("RCON ist ein zusätzlicher Zugang und wird nur bei Bedarf verbunden. Host und Kennwort dienen auch als HTTP-Fallback, wenn dort keine eigene URL bzw. kein eigenes Kennwort eingetragen ist.", "RCON is an additional connection, established on demand. Its host and password are also HTTP fallbacks when no separate URL or password is supplied."),
        ["SetupHttpHint"] = ("ggCON HTTP API: Bevorzugter Zugang für Spieler, Logs und unterstützte Serveraktionen. Entweder Host + HTTP-Port verwenden oder eine vollständige Basis-URL eintragen.", "ggCON HTTP API: preferred access for players, logs and supported server actions. Use host + HTTP port, or enter a complete base URL."),
        ["SetupLogFallback"] = ("Log-Dateimuster (nur SFTP-Fallback)", "Log file patterns (SFTP fallback only)"),
        ["SetupStartupHint"] = ("Nur konfigurierte Funktionen aktivieren. Autostart bedeutet: Der Dienst startet beim Öffnen von Red Raven. Er startet weder den SCUM-Server noch lädt er automatisch jede Konfiguration hoch.", "Enable only configured features. Automatic startup runs the service when Red Raven opens. It does not start the SCUM server or automatically upload every configuration."),
        ["IntegrationsMaintenance"] = ("Erweitert", "Advanced"),
        ["IntegrationsHint"] = ("Optional für Betreiber mit eigener Homepage. Ohne passende Website-Endpunkte und gemeinsame geheime Tokens deaktiviert lassen. Diese Funktionen sind nicht für die normale Servereinrichtung nötig.", "Optional for operators with their own website. Leave disabled unless matching website endpoints and shared secret tokens exist. Not needed for regular server setup."),
        ["WebsiteIntegrations"] = ("Homepage-Anbindungen (optional)", "Website connections (optional)"),
        ["UpdatesMaintenance"] = ("Updates", "Updates"),
        ["UpdatesHint"] = ("Updates kommen aus stabilen GitHub-Releases. Update installieren lädt und prüft das Paket und startet das Tool neu. Eigene Daten bleiben erhalten; ersetzte Programmdateien werden gesichert. Git-Commits allein sind keine Updates.", "Updates come from stable GitHub releases. Install update downloads and verifies the package, then restarts the tool. User data is preserved and replaced program files are backed up. Git commits alone are not updates."),
