        ["HelpHost"] = ("Server-IP oder Hostname ohne http:// und ohne Port. Wird auch für HTTP verwendet, wenn keine Basis-URL angegeben ist.", "Server IP or hostname without http:// or port. Also used for HTTP when no base URL is supplied."),
