        ["HelpDiscordStatusToken"] = ("Token eines zweiten Bots, nur für die Spieleranzahl-Präsenz. Nur nötig, wenn der separate Status-Bot aktiviert ist.", "Token of a second bot, only for player-count presence. Required only when the separate status bot is enabled."),
