        ["HelpDiscordGameBridgeMessageType"] = ("Ingame-Farbe/Typ für Discord-Nachrichten, z. B. Cyan. Nicht die Discord-Embed-Farbe.", "In-game message color/type for Discord messages, e.g. Cyan. Not the Discord embed color."),
        ["HelpDiscordChatLogEmbedsEnabled"] = ("Sendet Ingame-Chatzeilen als Embeds in den Chatlog-Kanal, während die Logweiterleitung läuft.", "Sends in-game chat lines as embeds to the chat log channel while forwarding is running."),
        ["HelpDiscordVehicleLogEmbedsEnabled"] = ("Sendet Fahrzeug-Logmeldungen über die Discord-Logweiterleitung. Kein Versicherungsnachweis allein.", "Sends vehicle log messages through Discord log forwarding. Not proof of insurance eligibility by itself."),
        ["HelpPaidVotesEnabled"] = ("Aktiviert den Kauf von Abstimmungen mit Ingame-Geld. Der Chatmonitor und ggCON HTTP müssen funktionieren.", "Enables buying votes with in-game money. The chat monitor and ggCON HTTP must work."),
