        ["HelpVoteInsufficientFundsResponse"] = ("Antwort bei zu wenig Ingame-Geld. Platzhalter {cost}, {balance} und {name} verwenden.", "Response when in-game funds are insufficient. Use {cost}, {balance} and {name}."),
        ["HelpVotePurchaseSuccessResponse"] = ("Nachricht nach erfolgreicher Bezahlung und gestarteter Abstimmung. Unterstützt {name} und {cost}.", "Message after successful payment and vote startup. Supports {name} and {cost}."),
        ["HelpNewPlayerWelcomeEnabled"] = ("Begrüßt erstmals erkannte neue Spieler. Benötigt den laufenden Chatmonitor und Login-Daten.", "Welcomes newly detected first-time players. Requires the running chat monitor and login data."),
        ["HelpNewPlayerWelcomeMessageType"] = ("Farbe/Typ der Begrüßung im Spielchat, z. B. Cyan.", "Color/type of the welcome message in game chat, e.g. Cyan."),
