        ["HelpWeeklyTaskDbRemoteFilePath"] = ("Vollständiger SFTP-Pfad zu SCUM.db, z. B. /Serveradresse_Port/SaveFiles/SCUM.db. Kein Homepage- oder lokaler Pfad.", "Full SFTP path to SCUM.db, e.g. /Serveraddress_Port/SaveFiles/SCUM.db. Not a website or local path."),
        ["HelpWeeklyTaskPollMinutes"] = ("Minuten zwischen Datenbank-Scans. Jeder Scan lädt SCUM.db. Höhere Werte entlasten den Server, aktualisieren Fortschritte aber seltener.", "Minutes between database scans. Each scan downloads SCUM.db. Higher values reduce server load but refresh progress less often."),
        ["HelpWeeklyTaskOnlyWhenPlayersOnline"] = ("Keine Datenbank-Scans bei leerem Server. Nächster Scan erfolgt erst wieder mit Online-Spielern.", "Skip database scans when the server is empty. Scans resume when players are online."),
        ["HelpChallengeMessageLanguage"] = ("Sprache der Ingame-Herausforderungsnachrichten. Unabhängig von der Sprache der Tool-Oberfläche.", "Language of in-game challenge announcements. Independent of the tool's interface language."),
        ["HelpLocalWebAdminPort"] = ("Freier lokaler TCP-Port, z. B. 8787. LAN-Zugriff braucht eine passende Firewall-Freigabe. Nicht ins öffentliche Internet freigeben; der Sitzungslink ist geheim.", "Unused local TCP port, e.g. 8787. LAN access needs a matching firewall rule. Do not expose to the public Internet; the session link is secret."),
        ["HelpAutoMessagesIntervalMinutes"] = ("Minuten zwischen automatisch geposteten Nachrichten aus der Warteschlange.", "Minutes between automatic queue messages."),
        ["HelpAutoMessagesMaxLength"] = ("Maximale Zeichenlänge der Ingame-Nachrichten. Kurze Nachrichten vermeiden Abschneiden durch den Server.", "Maximum character length of in-game messages. Short messages avoid server truncation."),
        ["HelpAutoMessagesOnlyWhenPlayersOnline"] = ("Keine automatischen Nachrichten, solange niemand online ist.", "Do not broadcast automatic messages while nobody is online."),
        ["HelpAutoMessagesNoChallengeText"] = ("Ersatztext, falls die Nachricht aktive Community-Herausforderungen zeigen soll, aber keine laufen.", "Fallback text when a message should show active community challenges but none are running."),
        ["HelpScriptPollSeconds"] = ("Sekunden zwischen Prüfungen der Skript-Engine. Kleinere Werte erkennen Zonen schneller, erhöhen aber die Last.", "Seconds between script engine polls. Lower values detect zones faster but increase load."),
        ["HelpRandomQuestScheduledMode"] = ("Aktiviert den zentralen Event-Zeitplan. Gilt für alle zufälligen Events, nicht pro Skript.", "Enables the central event schedule. Applies to all random events, not separately to each script."),
        ["HelpRandomQuestRestartTimes"] = ("Geplante Neustartzeiten als HH:mm, durch Kommas getrennt. Lokale Zeit dieses PCs. Beispiel: 04:00,10:00,16:00,22:00.", "Scheduled restart times as comma-separated HH:mm. Uses this PC's local time. Example: 04:00,10:00,16:00,22:00."),
        ["HelpRandomQuestIntervalMinutes"] = ("Minuten zwischen neuen zufälligen Events im zentralen Zeitplan.", "Minutes between new random events in the central schedule."),
        ["HelpRandomQuestStartDelayMinutes"] = ("Wartezeit in Minuten nach einem geplanten Neustart, bevor Events beginnen dürfen.", "Delay in minutes after a scheduled restart before events may begin."),
        ["HelpSettingRandomizerRemoteFilePath"] = ("Vollständiger SFTP-Pfad zur ServerSettings.ini. Wird für Katalog, Vorschau und Upload verwendet. Vor Anwendung einen Preview-Test machen.", "Full SFTP path to ServerSettings.ini. Used for catalog, preview and upload. Test with Preview before applying."),
        ["HelpSettingRandomizerScheduleTimes"] = ("Upload-/Würfelzeiten als HH:mm, durch Kommas getrennt, in lokaler PC-Zeit. Beispiel: 03:55,09:55. Wirksamkeit hängt vom Server-Neuladen der Einstellungen ab.", "Roll/upload times as comma-separated HH:mm in the PC's local time. Example: 03:55,09:55. Changes take effect when the server reloads settings."),
        ["HelpSettingRandomizerDiscordAnnouncementEnabled"] = ("Zeigt die zuletzt hochgeladenen Randomizer-Werte im bestehenden Serverstatus-Embed. Keine separate Upload-Nachricht.", "Shows the latest uploaded randomizer values in the existing server status embed. No separate upload message."),
        ["HelpEconomyOverrideRemoteFilePath"] = ("Vollständiger SFTP-Pfad zur EconomyOverride.json. Änderungen werden erst nach SCUM-Serverneustart wirksam.", "Full SFTP path to EconomyOverride.json. Changes take effect only after a SCUM server restart."),
        ["HelpEconomyLogsRemoteDirectory"] = ("SFTP-Verzeichnis mit economy_*.log. Hier werden Trader-Käufe und -Verkäufe eingelesen.", "SFTP directory containing economy_*.log. Trader purchases and sales are read here."),
        ["HelpEconomyLogPattern"] = ("Dateimuster der Trade-Logs, z. B. economy_*.log. Nicht die EconomyOverride.json.", "Trade log filename pattern, e.g. economy_*.log. Not EconomyOverride.json."),
        ["HelpEconomyPollMinutes"] = ("Minuten zwischen Economy-Logscans. Bestimmt, wie oft neue Trades in die Preisberechnung eingehen.", "Minutes between economy log scans. Controls how often new trades enter price calculations."),
        ["HelpEconomyRecoveryHalfLifeHours"] = ("Stunden, bis sich die Preisabweichung ohne neue Trades halbiert. Beispiel: 336 = 14 Tage. Hoher Wert = langsame Erholung.", "Hours for a price deviation to halve without new trades. Example: 336 = 14 days. Higher = slower recovery."),
        ["HelpEconomyPurchaseImpactPercent"] = ("Einfluss eines Spieler-Kaufs auf die Preisabweichung, in Prozent. Höhere Werte lassen Nachfrage stärker wirken.", "Impact of a player's purchase on price deviation, in percent. Higher values increase demand's effect."),
        ["HelpEconomySaleImpactPercent"] = ("Einfluss eines Spieler-Verkaufs auf die Preisabweichung, in Prozent. Höhere Werte lassen das Angebot stärker wirken.", "Impact of a player's sale on price deviation, in percent. Higher values increase supply's effect."),
        ["HelpEconomyMaximumPurchaseMultiplier"] = ("Obergrenze des Kaufpreises als Faktor des Basispreises. Beispiel: 12 = maximal zwölfmal so teuer.", "Purchase price ceiling as a base-price multiplier. Example: 12 = at most twelve times the base price."),
        ["HelpEconomyMinimumSellPrice"] = ("Mindest-Auszahlung beim Verkauf in Ingame-Geld. Artikel, deren Basispreis darunter liegt, werden nicht künstlich teurer gemacht.", "Minimum sale payout in in-game money. Items whose base price is lower are not artificially made more expensive."),
        ["HelpEconomyAutoUpload"] = ("Erlaubt automatische Uploads zu den eingetragenen Zeiten. Aktiviert erst nach einer geprüften Vorschau. Der Server muss die Datei anschließend per Neustart laden.", "Allows automatic uploads at configured times. Enable only after checking a preview. The server must then load the file on restart."),
        ["HelpEconomyUploadTimes"] = ("Uploadzeiten als HH:mm, durch Kommas getrennt, in lokaler PC-Zeit. Sinnvoll kurz vor Serverneustarts.", "Upload times as comma-separated HH:mm in the PC's local time. Usually shortly before server restarts."),
        ["HelpWeeklyTaskWebApiEnabled"] = ("Optional: Fortschritte an deine kompatible Homepage übertragen. Braucht HTTPS-Endpunkt und denselben geheimen Token auf beiden Seiten.", "Optional: publish progress to your compatible website. Requires an HTTPS endpoint and the same secret token on both sides."),
        ["HelpWeeklyTaskWebApiEndpointUrl"] = ("Vollständiger HTTPS-Push-Endpunkt deiner Homepage, nicht die sichtbare Usercenter-Seite. Beispiel im Einrichtungsabschnitt.", "Full HTTPS push endpoint on your website, not the visible user center page. See the setup example."),
        ["HelpWebsiteToken"] = ("Gemeinsamer geheimer API-Token mit mindestens 16 Zeichen. Auf Homepage und Tool identisch einstellen. Kein ggCON-Kennwort, nicht an Spieler weitergeben.", "Shared secret API token, at least 16 characters. Set identically on the website and tool. Not a ggCON password; never share with players."),
        ["HelpEconomyWebApiEnabled"] = ("Optional: Economy-Daten an eine kompatible Börsenseite auf deiner Homepage senden.", "Optional: publish economy data to a compatible market page on your website."),
        ["HelpEconomyWebApiEndpointUrl"] = ("Vollständiger HTTPS-Endpunkt für Economy-Pushes. Muss auf deiner Homepage installiert sein; nicht die öffentliche Börsenseite.", "Full HTTPS endpoint for economy pushes. Must be installed on your website; not the public market page."),
        ["HelpShopOrdersEnabled"] = ("Optional: Spieler holen Homepage-Bestellungen per /bestellung bzw. /order ab. Braucht Worker-Endpunkt, gemeinsamen Token und laufenden Chatmonitor.", "Optional: players claim website orders via /bestellung or /order. Requires a worker endpoint, shared token and running chat monitor."),
        ["HelpShopWorkerApiEndpointUrl"] = ("HTTPS-Worker-Endpunkt deiner kompatiblen Shop-Installation, nicht die Shop-Seite. Red Raven fragt nur auf einen Abholbefehl hin an.", "HTTPS worker endpoint of your compatible shop installation, not the shop page. Red Raven requests an order when a claim command arrives."),
        ["HelpAutoCheckForUpdates"] = ("Prüft beim Toolstart auf eine neue Version. Installiert Updates nicht automatisch.", "Checks for a newer version at tool startup. Does not install updates automatically."),
        ["HelpUpdateLatestJsonUrl"] = ("Standard: GitHub-Releases von LMNT-Gaming/ScumRconTool. Die alte offizielle Homepage-URL wird automatisch auf GitHub umgeleitet. Eigene latest.json-Feeds müssen HTTPS-Download und SHA-256 enthalten.", "Default: GitHub releases of LMNT-Gaming/ScumRconTool. The old official website URL automatically uses GitHub. Custom latest.json feeds must supply an HTTPS download and SHA-256 checksum."),
        ["HelpUsageDirectoryEnabled"] = ("Freiwillige Veröffentlichung in der LMNT-Serverliste. Keine Voraussetzung für Red Raven. Übertragene Daten stehen unter dieser Option.", "Opt-in listing in the LMNT server directory. Not required for Red Raven. Published fields are described below."),
        ["HelpUsageDirectoryEndpointUrl"] = ("API der optionalen LMNT-Serverliste. Nur ändern, wenn du eine kompatible eigene API betreibst.", "API for the optional LMNT server directory. Change only if you operate a compatible API."),
        ["HelpVehicleInactivityWarningEnabled"] = ("Warnt vor Löschung wegen Inaktivität. Benötigt SFTP für SCUM.db und ServerSettings.ini sowie einen Discord-Textkanal.", "Warns before deletion due to inactivity. Requires SFTP for SCUM.db and ServerSettings.ini, plus a Discord text channel."),
        ["HelpVehicleInactivityWarningHours"] = ("Stunden vor der voraussichtlichen Löschung warnen. Beispiel: 12. Serverregel MaximumTimeOfVehicleInactivity bleibt unverändert.", "Hours before predicted deletion to warn. Example: 12. The MaximumTimeOfVehicleInactivity server rule is not changed."),
        ["HelpVehicleInactivityScanMinutes"] = ("Minuten zwischen Datenbankprüfungen. Empfohlen: 60. Kürzeres Intervall lädt SCUM.db häufiger.", "Minutes between database checks. Recommended: 60. Shorter intervals download SCUM.db more often."),
        ["HelpVehicleInsuranceEnabled"] = ("Aktiviert Versicherungen per Chatbefehl. Benötigt ggCON HTTP, Chatmonitor und konfigurierte Fahrzeugpreise.", "Enables insurance via chat commands. Requires ggCON HTTP, the chat monitor and configured vehicle prices."),
        ["HelpVehicleInsuranceDefaultWeeklyPrice"] = ("Wochenpreis für Fahrzeugtypen ohne eigenen Preis. Ingame-Geld, kein Echtgeld.", "Weekly price for vehicle types without a specific price. In-game money, not real money."),
        ["HelpVehicleInsuranceTwoWeekDiscountPercent"] = ("Prozent Rabatt auf zwei Wochenpreise. Beispiel: 10 bedeutet 10 % Rabatt für zwei Wochen.", "Percentage discount on two weekly premiums. Example: 10 means 10% off a two-week policy."),
        ["HelpVehicleInsuranceFourWeekDiscountPercent"] = ("Prozent Rabatt auf vier Wochenpreise. Beispiel: 20 bedeutet 20 % Rabatt für vier Wochen.", "Percentage discount on four weekly premiums. Example: 20 means 20% off a four-week policy."),
        ["HelpVehicleInsuranceWebEnabled"] = ("Optional: Versicherungen mit einer kompatiblen Usercenter-Seite synchronisieren. Nicht für Ingame-Versicherungen erforderlich.", "Optional: sync insurance with a compatible user center page. Not required for in-game insurance."),
        ["HelpVehicleInsuranceWebEndpoint"] = ("HTTPS-Endpunkt der Versicherungs-Synchronisierung auf deiner Homepage. Nicht die sichtbare Fahrzeugliste.", "HTTPS endpoint for insurance synchronization on your website. Not the visible vehicle list."),
        ["HelpAutoStartScripts"] = ("Startet die Skript-Engine beim Öffnen von Red Raven. Event-Zeitplan unter Skriptzone einstellen; spawnt nicht sofort alle Skripte.", "Starts the script engine when Red Raven opens. Configure event timing under Script zone; does not immediately spawn every script."),
        ["HelpAutoStartDiscordChatLogs"] = ("Startet Discord-Logweiterleitung beim Toolstart. Braucht Bot-Token, Kanal und eine konfigurierte Logquelle.", "Starts Discord log forwarding at tool startup. Requires bot credentials, channel and a configured log source."),
        ["HelpAutoStartDiscordServerStatusMessage"] = ("Aktualisiert das Serverstatus-Embed automatisch. Der Hauptbot sendet es in den eingetragenen Statuskanal.", "Automatically updates the server status embed. The main bot sends it to the configured status channel."),
        ["HelpAutoStartDiscordBotStatus"] = ("Aktualisiert die Spieleranzahl in der Bot-Präsenz automatisch. Bei getrenntem Status-Bot wird dessen Präsenz verwendet.", "Automatically updates player count in the bot presence. Uses the separate status bot when enabled."),
        ["HelpAutoStartChatCommands"] = ("Startet den Chatmonitor beim Toolstart. Benötigt für Chatbefehle, Codes, Quiz, Votes, Versicherungen und Shop-Abholung.", "Starts the chat monitor at tool startup. Required for chat commands, codes, quiz, votes, insurance and shop claims."),
        ["HelpAutoStartJoinCommands"] = ("Startet die Ausführung konfigurierter Join-Befehle beim Toolstart. Die Regeln werden im Join-Commands-Tab gepflegt.", "Starts configured join-command processing at tool startup. Configure rules in the Join commands tab."),
        ["HelpAutoStartWeeklyTasks"] = ("Startet den Challenge-Monitor beim Toolstart. Ziele, Datenbankpfad und Scanintervall unter Herausforderungen konfigurieren.", "Starts the challenge monitor at tool startup. Configure goals, database path and scan interval under Challenges."),
        ["HelpAutoStartSettingRandomizer"] = ("Aktiviert den Randomizer-Zeitplan beim Toolstart. Würfelt zu den konfigurierten Zeiten, nicht sofort beim Aktivieren dieses Häkchens.", "Enables the randomizer schedule at tool startup. Rolls at configured times, not immediately when checking this box."),
        ["HelpAutoStartEconomy"] = ("Startet Economy-Logscans beim Toolstart. Automatischer Datei-Upload hat einen eigenen Schalter im Economy-Tab.", "Starts economy log scans at tool startup. Automatic file upload has a separate option in the Economy tab."),
        ["HelpAutoStartAutoMessages"] = ("Startet die Nachrichten-Warteschlange beim Toolstart. Texte und Intervall unter Auto-Nachrichten einstellen.", "Starts the message queue at tool startup. Configure text and interval under Automatic messages."),
    };
}
